export const zInteractionActionResult = z
  .object({
    command_id: z.string().min(1),
    pause_revision: z.number().int().max(Number.MAX_SAFE_INTEGER).min(1),
    kind: z.enum(["accepted", "native_consumed", "validation_failed", "unknown", "cancelled"]),
  })
  .strict()

export const zChatInteractionState = z
  .object({
    interaction_revision: z.number().int().max(Number.MAX_SAFE_INTEGER).min(1),
    pause_revision: z.number().int().max(Number.MAX_SAFE_INTEGER).min(0),
    pause_ref: z.union([z.string().min(1), z.null()]),
    phase: z.enum(["active", "waiting", "resuming", "terminal"]),
    groups: z.array(zInteractionGroup),
    action_result: z.union([zInteractionActionResult, z.null()]),
  })
  .strict()

export const zChatTodo = z
  .object({ todos: z.array(z.object({ content: z.string().min(1), status: z.enum(["pending", "in_progress", "completed"]) }).strict()).max(100) })
  .strict()

export const zChatActivity = z.union([
  z
    .object({
      activity: z.literal("tool"),
      activity_id: z.string().min(68),
      segment_id: z.string().min(68),
      status: z.enum(["running", "completed", "failed"]),
      display_code: z.enum([
        "tool.execution",
        "tool.file.read",
        "tool.mcp.discover",
        "tool.mcp.describe",
        "tool.mcp.call",
        "tool.web.search",
        "tool.web.fetch",
        "tool.file.write",
        "tool.file.deliver",
      ]),
      display_detail: z
        .object({ kind: z.enum(["file", "mcp_tool"]), name: z.string().min(1), virtual_path: z.string().min(1).optional() })
        .strict()
        .optional(),
      action_title: z.string().min(1).optional(),
    })
    .strict(),
  z
    .object({
      activity: z.literal("subagent"),
      activity_id: z.string().min(68),
      segment_id: z.string().min(68),
      status: z.enum(["running", "completed", "failed"]),
      display_code: z.literal("subagent.execution"),
    })
    .strict(),
  z
    .object({
      activity: z.literal("skill"),
      activity_id: z.string().min(68),
      preflight_id: z.string().min(68),
      source_refs: z.array(z.string().min(7)).min(1).max(16),
      phase: z.enum(["resolving", "loading", "ready", "failed"]),
      error_code: z.enum(["skill_resolve_failed", "skill_load_failed"]).optional(),
      display_skills: z.array(zSkillDisplay).max(16).optional(),
    })
    .strict(),
])

export const zChatRunCompleted = z
  .object({
    status: z.enum(["completed", "cancelled"]),
    token_usage: z
      .object({ input_tokens: z.number().int().max(Number.MAX_SAFE_INTEGER).min(0), output_tokens: z.number().int().max(Number.MAX_SAFE_INTEGER).min(0) })
      .strict()
      .optional(),
    final_message_id: z.string().min(1).optional(),
  })
  .strict()
  .refine((value) => value.final_message_id === undefined || value.status === "completed", "Final answer requires completed run")
